deltas.after:
env:
  CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
  CLOUDFLARE_ZONE_ID: ${{ secrets.CLOUDFLARE_ZONE_ID }}
  DEPLOY_PUBLIC_BASE_URL: ${{ vars.DEPLOY_PUBLIC_BASE_URL }}
  DEPLOY_RELEASE_URL: ${{ vars.DEPLOY_RELEASE_URL }}
  FPM_RELOAD_MODE: ${{ vars.FPM_RELOAD_MODE }}
  FPM_SERVICE: ${{ vars.FPM_SERVICE }}
  EXPECTED_RELEASE: ${{ github.sha }}
permissions:
  contents: read

steps:
  - name: Checkout source
    uses: actions/checkout@v5

  # Intentionally fail before SSH or schema mutations until an independently
  # reviewed, dynamic release endpoint and runtime policy are configured.
  - name: Require verifiable deployment prerequisites
    id: preflight
    timeout-minutes: 2
    run: |
      python3 tools/ci/verify-deployment.py preflight
      python3 tools/ci/verify-deployment.py probe-current

  - name: Setup Node for immutable Fokus Law assets
    uses: actions/setup-node@v5

deltas.before:
  run: node tools/generate-fokus-law-assets.mjs --output-root "$GITHUB_WORKSPACE" --staging-dir "$RUNNER_TEMP/fokus-law-assets"

- name: Configure SSH
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
  run: node tools/generate-fokus-law-assets.mjs --output-root "$GITHUB_WORKSPACE" --staging-dir "$RUNNER_TEMP/fokus-law-assets"

- name: Configure SSH
  id: ssh
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" exit

- name: Verify Law schema before publishing application code
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" exit

- name: Verify Law schema before publishing application code
  id: schema
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    ssh "${ssh_args[@]}" "$target" "set -eu; cd '$DEPLOY_PATH'; php '$remote_dir/prepublish-law-schema.php' '$DEPLOY_PATH'; rm -f '$remote_dir/prepublish-law-schema.php' '$remote_dir/2026_10_30_160000_add_encrypted_details_to_law_contacts.php'; rmdir '$remote_dir'"

- name: Stage immutable Fokus Law assets before application references
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    ssh "${ssh_args[@]}" "$target" "set -eu; cd '$DEPLOY_PATH'; php '$remote_dir/prepublish-law-schema.php' '$DEPLOY_PATH'; rm -f '$remote_dir/prepublish-law-schema.php' '$remote_dir/2026_10_30_160000_add_encrypted_details_to_law_contacts.php'; rmdir '$remote_dir'"

- name: Stage immutable Fokus Law assets before application references
  id: assets
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
      "set -eu; cd '$DEPLOY_PATH'; sha256sum --check -" < "$RUNNER_TEMP/fokus-law-assets/checksums.sha256"

- name: Sync application source
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
      "set -eu; cd '$DEPLOY_PATH'; sha256sum --check -" < "$RUNNER_TEMP/fokus-law-assets/checksums.sha256"

- name: Sync application source
  id: files
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
      ./ "$DEPLOY_USER@$DEPLOY_HOST:$DEPLOY_PATH/"

- name: Check server runtime
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
      ./ "$DEPLOY_USER@$DEPLOY_HOST:$DEPLOY_PATH/"

- name: Check server runtime
  id: runtime
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; printf 'user='; id -un; printf 'php='; php -r 'echo PHP_VERSION, PHP_EOL;'; printf 'composer='; composer --version; test -f composer.json; test -f composer.lock; test -f .env"

- name: Install dependencies on server
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; printf 'user='; id -un; printf 'php='; php -r 'echo PHP_VERSION, PHP_EOL;'; printf 'composer='; composer --version; test -f composer.json; test -f composer.lock; test -f .env"

- name: Install dependencies on server
  id: dependencies
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    exit 1

- name: Migrate database on server
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    exit 1

- name: Migrate database on server
  id: migrations
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan migrate --force --no-interaction"

- name: Configure public Datajud access on server
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan migrate --force --no-interaction"

- name: Configure public Datajud access on server
  id: datajud_config
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    printf '%s' "$DATAJUD_API_KEY" | ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php deploy/configure-datajud.php"

- name: Optimize Laravel on server
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    printf '%s' "$DATAJUD_API_KEY" | ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php deploy/configure-datajud.php"

- name: Optimize Laravel on server
  id: caches
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan optimize"

- name: Synchronize automatic contact age tags
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan optimize"

- name: Synchronize automatic contact age tags
  id: tags
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan law:sync-contact-age-tags --no-interaction"

- name: Check Datajud configuration and public endpoint
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan law:sync-contact-age-tags --no-interaction"

- name: Check Datajud configuration and public endpoint
  id: datajud
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
    ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan law:datajud-status; php artisan law:datajud-status --probe || printf '%s\n' '::warning::O Datajud não confirmou resposta externa; consulte o diagnóstico acima.'"

- name: Ensure Laravel scheduler is active
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.after:
    ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; php artisan law:datajud-status; php artisan law:datajud-status --probe || printf '%s\n' '::warning::O Datajud não confirmou resposta externa; consulte o diagnóstico acima.'"

- name: Ensure Laravel scheduler is active
  id: scheduler
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}

deltas.before:
  run: |
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "set -eu; cd '$DEPLOY_PATH'; bash deploy/install-scheduler.sh; php artisan schedule:list --no-ansi | grep law-datajud"

- name: Reload PHP-FPM opcache on server
  env:
    DEPLOY_HOST: ${{ secrets.DEPLOY_HOST }}
    DEPLOY_PORT: ${{ secrets.DEPLOY_PORT }}
    DEPLOY_USER: ${{ secrets.DEPLOY_USER }}
    DEPLOY_PATH: ${{ secrets.DEPLOY_PATH }}
  run: |
    ssh -o ConnectTimeout=20 -o ConnectionAttempts=1 -p "$DEPLOY_PORT" "$DEPLOY_USER@$DEPLOY_HOST" "sudo -n systemctl reload clp-php-fpm.service || sudo -n systemctl restart clp-php-fpm.service" || echo "PHP-FPM reload requires server-side sudo; continuing deployment."

- name: Purge Cloudflare cache
  if: ${{ env.CLOUDFLARE_API_TOKEN != '' && env.CLOUDFLARE_ZONE_ID != '' }}
  run: |
    curl --fail-with-body --request POST \

deltas.after:
      --header "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
      --header "Content-Type: application/json" \
      --data '{"purge_everything":true}'

- name: Verify application health and expected active release
  id: release
  timeout-minutes: 2
  run: python3 tools/ci/verify-deployment.py verify

- name: Report each publication phase
  if: ${{ always() }}
  env:
    PHASE_PREFLIGHT: ${{ steps.preflight.outcome }}
    PHASE_SSH: ${{ steps.ssh.outcome }}
    PHASE_SCHEMA: ${{ steps.schema.outcome }}
    PHASE_ASSETS: ${{ steps.assets.outcome }}
    PHASE_FILES: ${{ steps.files.outcome }}
    PHASE_RUNTIME: ${{ steps.runtime.outcome }}
    PHASE_DEPENDENCIES: ${{ steps.dependencies.outcome }}
    PHASE_MIGRATIONS: ${{ steps.migrations.outcome }}
    PHASE_DATAJUD_CONFIG: ${{ steps.datajud_config.outcome }}
    PHASE_CACHES: ${{ steps.caches.outcome }}
    PHASE_TAGS: ${{ steps.tags.outcome }}
    PHASE_DATAJUD: ${{ steps.datajud.outcome }}
    PHASE_SCHEDULER: ${{ steps.scheduler.outcome }}
    PHASE_SERVICES: ${{ steps.services.outcome }}
    PHASE_CDN: ${{ steps.cdn.outcome }}
    PHASE_RELEASE: ${{ steps.release.outcome }}
  run: python3 tools/ci/summarize-deployment.py
